const expandedLessons=[
 {id:13,title:'成本、报价与稀缺：为什么电价不是平均成本',desc:'从燃料账单走到短期价格，识别固定成本、增量成本和稀缺信号。',minutes:22,
 sections:[
 ['先决定你要回答哪一个问题','“今天多发一度电是否划算”和“建一座电站是否划算”需要不同成本。前者主要比较新增燃料、耗材和运行磨损；后者还要承担投资与长期固定支出。已发生的建设费不会因这一小时停发而收回，所以不能把年平均度电成本直接当作短期最低报价。'],
 ['把燃料成本换到电量单位','设机组生产 1 MWh 电耗用 7 GJ 燃料，燃料价 40 元/GJ。新增燃料费为 7×40=280 元/MWh，另有变动运维 20 元/MWh，简化增量成本为 300 元/MWh。热耗越高意味着同样电量耗用更多燃料。燃料单位、热值口径和含税条件必须对应。'],
 ['成本不自动等于报价','在价格接受者、无启停约束的教学模型中，按增量成本报价有助于判断经济调度；现实报价还可能包含启停、机会成本，并受到申报和成本审核规则约束。观察到报价高于燃料成本时，先找成本与约束证据，不能立即判定操纵，也不能默认任何加价都合理。'],
 ['边际价格留下什么收入','若出清价 420 元/MWh、出力 50 MW 持续 1 小时，收入为 21,000 元；增量运行支出 15,000 元，差额 6,000 元用于覆盖固定支出等。这是该时段的贡献毛益，不是全年净利润。长期收入能否覆盖投资，要连接出力小时数、低价时段和容量等合规收入。'],
 ['供给接近边界时的稀缺','当可用机组、线路和备用接近上限，多满足一点需求可能代价很高。部分市场通过稀缺定价机制表达这一信号，但价格上限、备用需求与停电损失的处理各不相同。不要在供给缺额时沿用最后一台机组报价假装已经平衡；先报告缺额，再研究该地区的处置规则。']
 ],quiz:{q:'机组本小时收入减去新增运行支出后剩余 6,000 元，最准确的说法是？',options:['本小时用于覆盖固定支出等的贡献毛益','全年可分配净利润','不考虑成本的全部销售收入'],answer:0,explain:'短时贡献毛益仍要承担固定成本、融资和税费等，不能直接称为项目净利润。'},
 guide:{goal:'把燃料价格换成增量度电成本，并算出一个时段的贡献毛益。',pre:[0,1,2],terms:['热耗率','增量成本','贡献毛益','稀缺定价'],example:['把成本与收入写在两列','假设热耗 7 GJ/MWh，燃料价 40 元/GJ，变动运维 20 元/MWh。①增量成本=7×40+20=300 元/MWh。②50 MW 运行 1 小时得到 50 MWh。③价格 420 时收入=50×420=21,000 元。④运行支出=50×300=15,000 元。⑤贡献毛益=6,000 元。未计固定支出。'],task:['同一机组热耗 7 GJ/MWh，燃料价改为 45 元/GJ，变动运维仍 20 元/MWh。简化增量成本是多少？',335,'元/MWh','7×45+20=335 元/MWh。不是 335 元/kWh，也未分摊建设费。']},sources:[curriculumSources.heat,curriculumSources.micro],pitfalls:['把短期贡献毛益当作全年净利润。','将固定成本平均分摊结果机械当作每小时最低报价。']},

 {id:14,title:'弹性需求与社会福利：电一定要全部买吗',desc:'让用户也能报价，比较新增用电价值与新增供电成本。',minutes:24,
 sections:[
 ['从固定需求走到愿付价格','前面的出清把需求当作必须满足的一个数。现在把需求分成几块，并给每块一个愿付价格：它表示在本教学模型中多获得 1 MWh 电给使用者带来的价值。它不是用电企业向客户收取的产品售价，也不是用电账单中的全部费用；真实需求偏好往往难以直接测得。'],
 ['按价值与成本配对','供给 A 有 40 MWh，成本 200 元/MWh；B 有 40 MWh，成本 500 元/MWh。需求 X 要 30 MWh，愿付 700；Y 要 30 MWh，愿付 350；Z 要 20 MWh，愿付 150。先安排价值较高需求与便宜供给，只有新增价值不低于新增成本时，交易才增加模型里的总福利。'],
 ['为什么少交易反而更有效','最优安排为 A 发 40 MWh，X 获 30、Y 获 10，B 与 Z 不参与。再给 Y 供应一度电将需要成本 500 的 B，却只产生价值 350，净收益为负。已成交需求价值为 30×700+10×350=24,500 元，生产成本 40×200=8,000 元，总福利为 16,500 元。'],
 ['价格分配收益，数量决定效率','用 350 元/MWh 作为本例的统一边际价格，用户侧剩余为 30×(700−350)=10,500 元，发电侧剩余为 40×(350−200)=6,000 元。两者相加等于 16,500。购买电能量的付款是交易双方之间的转移，在这个简化模型中相加后抵消，不能再次扣除而算两遍成本。'],
 ['把福利模型带回现实','供给安全、不可中断用户、外部环境成本和计量资格都会改变可行范围；愿付价格不能作为随意拉闸的依据。分段曲线在边界处还可能出现不唯一价格或部分成交，要说明采用的定价约定。本课先学习增量比较，不把结果宣传为任何地区的实际出清算法。']
 ],quiz:{q:'给愿付价格 350 元/MWh 的新增需求安排成本 500 元/MWh 的供给，会怎样改变本例总福利？',options:['每 MWh 增加 150 元','每 MWh 减少 150 元','总福利不受成本影响'],answer:1,explain:'新增价值减新增成本=350−500=−150 元/MWh，因此这笔新增交易降低总福利。'},
 guide:{goal:'按需求愿付价格与供给成本判断是否应该增加交易，并避免重复扣付款。',pre:[4,6,13],terms:['愿付价格','社会福利','消费者剩余','生产者剩余'],example:['先算数量，再算福利','①将供给按成本升序、需求按愿付价格降序。②A 的前 30 MWh 供 X，余 10 MWh 供 Y。③下一块供给 B 的 500 高于 Y 的 350，停止增加交易。④福利=30×700+10×350−40×200=16,500 元。⑤在教学价格 350 下，消费者剩余 10,500 加生产者剩余 6,000 核对同一总额。'],task:['自编新题：40 MWh 需求愿付 600 元/MWh，由成本 250 元/MWh 的供给完全满足。忽略其他成本，总福利是多少？',14000,'元','总福利=用电价值−生产成本=40×(600−250)=14,000 元。双方付款相互抵消，不再额外扣除。']},sources:[curriculumSources.micro,curriculumSources.wholesale],pitfalls:['把账单付款和生产成本同时从总福利中扣除。','把愿付价格理解为可以任意中断真实供电的授权。']},

 {id:15,title:'机组不是水龙头：启停、最小出力与爬坡',desc:'在按价格排序之外，检查机组运行是否可行以及跨时段成本。',minutes:24,
 sections:[
 ['开机决定与出力决定不同','开机决定是“这一段时间机组是否运行”，出力决定是“已开机后发多少”。停机机组即使边际成本低，也可能因为启动费、启动耗时和最小连续开机时长而不值得临时启动。把开机状态写为 0 或 1，再决定对应出力，可以帮助理解机组组合问题为什么比简单排序复杂。'],
 ['最低出力让便宜供给也有限制','假设某机组最大 80 MW、开机后最低 30 MW。允许的状态是停机 0，或运行在 30—80 MW；10 MW 不是合法运行点。低负荷时同时开启太多这类机组，可能造成总最低出力超过需求。此时要调整组合、外送或其他灵活资源，不能用任意小出力掩盖约束。'],
 ['爬坡限制连接相邻时段','机组上一时段为 40 MW，允许每 15 分钟最多升 10 MW，下一时段最多到 50 MW。即使容量是 80 MW，也不能直接跳到 80。计划时要同时检查向上和向下爬坡、初始状态及时间间隔；把每分钟指标误当成每小时指标，会严重误判备用与新能源跟踪能力。'],
 ['启动费为何改变最优选择','自编比较：需求新增 20 MW 持续 2 小时。新机组边际成本 200 元/MWh，启动费 3,000 元，且能以 20 MW 可行运行；已有机组增发成本 300 元/MWh。新机组总成本=40×200+3,000=11,000 元，已有机组=40×300=12,000 元，前者较低。若只需 1 小时，前者 7,000 高于后者 6,000。'],
 ['补偿与价格应分开阅读','带启停等约束的调度结果，不一定能靠单个边际电价覆盖所有被指令机组的申报成本。某些市场存在补偿或 uplift 安排，但适用条件、分摊与审核不同。比较方案要先得到满足所有约束的调度，再分别研究能量结算与额外补偿，不可直接给价格任意加上一笔启动费。']
 ],quiz:{q:'容量 80 MW、上一时段 40 MW、15 分钟向上爬坡限额 10 MW 的机组，下一 15 分钟末最高可到？',options:['80 MW','50 MW','10 MW'],answer:1,explain:'下一时段受爬坡约束：40+10=50 MW；容量上限仍需检查但本例未触及。'},
 guide:{goal:'在算报价之前检查启停、最小出力和相邻时段爬坡。',pre:[13,6],terms:['机组组合','最小出力','爬坡约束','启动成本','Uplift'],example:['把两种方案放在相同时间范围','①需求新增 20 MW，持续 2 小时，电量 40 MWh。②方案甲新开机：40×200+3,000=11,000 元。③方案乙已有机组增发：40×300=12,000 元。④两者均假设容量和爬坡可行，甲低 1,000 元。⑤若持续 1 小时，甲=7,000、乙=6,000，结论反转。启停选择要看整个持续期间。'],task:['机组当前 45 MW，每 15 分钟最多增加 12 MW，容量 70 MW。下一 15 分钟末最高可出力多少？',57,'MW','先算 45+12=57，再与容量 70 比较，取较小值。此题不涉及启动耗时。']},sources:[curriculumSources.operations,curriculumSources.load],pitfalls:['只按边际成本排序而忽略启动费与最低出力。','将爬坡的 MW/分钟与 MW/时段混用。']},

 {id:16,title:'负荷曲线与加权均价：一天的均价不等于你的电费',desc:'逐时对齐功率、电量与价格，区分时间平均和电量加权平均。',minutes:22,
 sections:[
 ['先画真实时间顺序','负荷曲线记录每一时段的用电功率；按功率大小重新排序可得到负荷持续曲线。后者适合看高负荷持续多久，却丢失先后关系。分析储能充放电、爬坡或前一时段状态时必须保留原时间顺序，不能在排序后的曲线上安排一次虚构的充放电。'],
 ['把每一格功率变成电量','每行至少写开始时间、时长、平均功率、电量和价格。自编三个 1 小时时段功率为 10、30、10 MW，则电量分别为 10、30、10 MWh。若第二行只有半小时，电量就改为 15 MWh。价格与计量曲线若采用不同颗粒度，要先按对应结算规则重采样或分配。'],
 ['用实际电量当权重','对应价格为 200、600、200 元/MWh，电能量费用=10×200+30×600+10×200=22,000 元。总用电 50 MWh，电量加权均价=22,000÷50=440 元/MWh。价格的简单平均为 333.33，不能乘总电量算这名用户的费用，因为用户恰好在贵时段用得更多。'],
 ['同样电量也可能是不同成本','另一用户每时段都用 50/3 MWh，总量仍 50 MWh，费用约 16,666.67 元。这种差异来自电量与价格的时间对应关系，不是单位换算错误。规划负荷移峰时要问哪些负荷真正可移、是否影响生产、移到何时；只用月总电量会隐藏这些机会和限制。'],
 ['从曲线走到后续课','负荷率=期间平均功率÷期间最大功率，本例为(50÷3)÷30≈55.56%。它描述曲线平坦程度，不能直接代表设备效率。发电项目还常看出力加权的捕获电价，零售商关心负荷加权购电成本；主体不同，权重也不同，并须区分电能量费用与完整到户账单。']
 ],quiz:{q:'用户大部分电量发生在高价时段，电量加权均价与价格简单平均可能是什么关系？',options:['加权均价可能更高','两者必然相等','加权均价只由总电量决定'],answer:0,explain:'权重来自每时段实际电量，电量与价格的对应关系决定加权结果。'},
 guide:{goal:'由逐时功率计算费用和加权均价，并说明时间平均为什么会误导。',pre:[0,2],terms:['负荷曲线','负荷持续曲线','电量加权均价','负荷率','捕获电价'],example:['三行表比一个月均价更有用','①三个时段均 1 小时，负荷 10/30/10 MW，价格 200/600/200 元/MWh。②电量 10/30/10 MWh，总量 50。③费用 2,000+18,000+2,000=22,000 元。④加权均价 22,000÷50=440 元/MWh。⑤检查：高价时段电量占 60%，因此加权结果高于 333.33 的时间平均。'],task:['两个 1 小时时段分别用电 20 与 40 MWh，价格 300 与 600 元/MWh。电量加权均价是多少？',500,'元/MWh','费用=20×300+40×600=30,000 元；除以 60 MWh 得 500 元/MWh。']},sources:[curriculumSources.load,curriculumSources.tariffs],pitfalls:['用价格简单平均乘用户总电量。','在按大小排序的持续曲线上安排储能时序。']},

 {id:17,title:'双节点网络：线路多一兆瓦值多少钱',desc:'用一条受限线路推导两个地点的电价及扩容的短期价值。',minutes:25,
 sections:[
 ['把网络压缩成两个地点','本课自行设置 A、B 两节点，仅一条 A→B 线路，不考虑网损和环流。A 有充足供给，增量成本 200 元/MWh，自用 20 MW；B 负荷 70 MW，本地供给成本 500 元/MWh。线路最多输送 40 MW，所有需求都须满足，计算 1 小时。此模型适合手算，但不是现实多网孔潮流模型。'],
 ['先求可行的最便宜出力','A 电源便宜，优先多送，但受线路上限约束只能送 40 MW。A 总发电=20+40=60 MW，B 本地发电=70−40=30 MW。逐节点核对：A 发 60 等于本地用 20 加外送 40；B 接收 40 加本地发 30 等于用 70。系统运行成本=60×200+30×500=27,000 元。'],
 ['用增加一点需求理解节点价格','在容量仍充足且约束状态不变时，A 多用 1 MW 可由 A 电源直接增发，成本每小时多 200 元；B 多用 1 MW 因线路已满，只能本地增加，成本每小时多 500 元。因此本例 A、B 节点能量价分别为 200、500 元/MWh。它们不是各自已有供给的平均成本。'],
 ['放宽线路上限的价值','若线路允许从 40 增至 41 MW，A 多发 1 MW、B 少发 1 MW，1 小时节省 500−200=300 元。这个 300 元/(MW·小时) 是当前状态下的边际约束价值。继续扩容到 B 本地机组退出或其他约束生效时，这个值会变；不能直接乘全年 8,760 小时宣称就是年收益。'],
 ['价格差与支付差额','按照本例节点价结算，用户电能量付款=20×200+70×500=39,000 元，机组电能量收入=60×200+30×500=27,000 元，差额 12,000=40×(500−200)。这是模型中的阻塞相关结算剩余，具体分配须看市场制度，既不是线路建设总利润，也不能同时计入每个项目收益。']
 ],quiz:{q:'本例线路容量从 40 增加到 41 MW，持续 1 小时，运行成本降低多少？',options:['200 元','300 元','500 元'],answer:1,explain:'替代 1 MWh 的 B 供给：500−200=300 元；这是此时约束状态下的边际价值。'},
 guide:{goal:'核对两节点平衡，用边际增量推导节点价和线路约束价值。',pre:[8,6],terms:['节点平衡','影子价格','阻塞剩余'],example:['按物理平衡推导价格','①A 用 20、B 用 70 MW，线路 40 MW。②A 发 60、B 发 30，总计 90。③1 小时成本 60×200+30×500=27,000 元。④A 新增需求边际成本 200，B 为 500。⑤线路多 1 MW 后，A 61、B 29，成本 26,700，节省 300 元。所有供给容量假设充足且不考虑网损。'],task:['将本例线路上限由 40 改为 50 MW，其他条件不变。B 本地机组在这个 1 小时时段发多少 MWh？',20,'MWh','B 负荷 70 MW，外来 50 MW，本地需 20 MW；乘 1 小时得到 20 MWh。']},sources:[curriculumSources.network,curriculumSources.energy],pitfalls:['把两节点无损单线模型当作完整潮流。','把某小时扩容边际价值不加条件外推全年。']},

 {id:18,title:'辅助服务机会成本：一份容量能卖两次吗',desc:'计算备用的容量占用与放弃电能量的价值，理解联合优化。',minutes:24,
 sections:[
 ['服务的对象先写清楚','电能量销售按 MWh 计量，备用购买的是规定时间内可调用的响应能力，调频还可能涉及信号跟踪与性能。只有满足响应速度、持续时间、计量和资格要求的能力才能参与。容量表上写着 50 MW，并不等于这 50 MW 在任何时刻都能提供相同服务。'],
 ['用同一物理上限核对承诺','自编机组最大出力 50 MW，若安排电能量 45 MW，只剩 5 MW 向上空间。要承诺 10 MW 向上备用，通常需把基础出力降到不高于 40 MW，且检查爬坡能力。能量 45 加备用 10 大于容量 50 的方案不可行；不要分别在两个收入表里都用满容量再相加。'],
 ['被放弃的利润就是机会成本','设能量价 400、机组增量成本 250 元/MWh。留出 10 MW 备用使 1 小时能量少发 10 MWh，放弃贡献毛益=10×(400−250)=1,500 元。备用可用能力单价若为 180 元/(MW·小时)，获得 1,800 元，在本例中比放弃的毛益多 300 元，尚未计服务磨损、测试与风险。'],
 ['中标备用不等于实际发电','备用在待命阶段没有必然发出 10 MWh。实际调用可能持续 5、15 或更多分钟，调用电量的结算应与能力报酬分别核对。若某服务按性能或里程支付，也不能把其单价写成元/MWh 后套能量公式。阅读资料时把产品、单位、考核和调用支付列成四列。'],
 ['联合优化的直观目的','系统需要同时安排能量与服务，在满足总需求、备用需求和每台资源约束下选择成本更低的组合。某台机组报价低，却可能留作备用更有价值；另一台发能量。这是资源配置问题，不是宣称所有市场都以同一公式补偿机会成本。储能还须加入 SOC、持续时长和恢复充电约束。']
 ],quiz:{q:'备用未被实际调用时，承诺 10 MW 持续 1 小时是否一定发了 10 MWh 电？',options:['一定是 10 MWh','不一定，需要实际调用记录','一定是 0 MW 容量'],answer:1,explain:'备用承诺是能力，可用报酬与实际调用电量是不同量。'},
 guide:{goal:'同时检查能量与服务的物理上限，并计算留出容量的机会成本。',pre:[5,15],terms:['机会成本','备用能力','联合优化','性能考核'],example:['先减能量，再加服务','①机组上限 50 MW，原本发 50。②留出 10 MW 向上备用后，能量出力 40。③1 小时放弃毛益=10×(400−250)=1,500 元。④备用能力收入=10×180×1=1,800 元。⑤差额 300 元，不等于实际调用收入，也未扣新增服务成本。题设假定具备相应响应能力。'],task:['某资源为 5 MW 备用持续留出 2 小时；被替代能量价 450、增量成本 300 元/MWh。放弃的贡献毛益是多少？',1500,'元','放弃电量=5×2=10 MWh；机会成本=10×(450−300)=1,500 元。']},sources:[curriculumSources.services,curriculumSources.wholesale],pitfalls:['把备用 MW 与能量 MWh 当同一商品。','能量与备用分别按满容量收益后直接叠加。']},

 {id:19,title:'资源充裕性与容量机制：一年有电不等于尖峰可靠',desc:'区分装机、可用能力和关键时段贡献，理解容量机制的履约逻辑。',minutes:24,
 sections:[
 ['安全运行与长期充裕性','运行安全关心此刻故障后系统能否稳住；充裕性关心未来需求增长、退役和天气变化下，是否有足够可用资源。全年总发电量多，不保证某个高峰小时不缺电。规划既要看每小时需求与资源可用性，也要看机组故障、燃料、输电和储能持续时间。'],
 ['铭牌容量不是可靠贡献','100 MW 光伏在夜间尖峰的贡献不能直接按 100 MW 计算；100 MW/200 MWh 储能也不能连续 10 小时满功率发电。可靠容量由评价方法、关键风险时段和资源组合决定。所谓折减系数是模型或规则结果，不是可以随意给不同技术贴上的永久百分比。'],
 ['容量机制购买什么','容量市场、容量补偿、可靠性期权或战略备用在设计上不同，共同关注资源在需要时的能力与义务。能量收入随实际发电量变化，容量收入往往关联通过认定、承诺期间和履约表现。不能因为某地有容量机制，就假定所有储能或分布式项目自动按铭牌容量拿钱。'],
 ['一个明确单位的收入示例','纯教学假设：某资源通过认定 80 MW，能力支付为 100 元/(kW·年)。先换算 80 MW=80,000 kW，年能力收入=80,000×100=8,000,000 元。该收入未扣履约处罚、交易成本和税费，也未加电能量收入。若仅认定 60 MW，就按 60,000 kW 算，而非仍用装机 80。'],
 ['评估机制时提出具体问题','先问目标可靠性如何定义、需求如何预测、资源如何认定、何时交付、故障怎样考核，再问费用谁承担。过高采购可能增加消费者成本，过低或考核太弱可能不改善可靠性。本课的简单折减和支付算例只帮助阅读，复杂系统还需要概率评估和连续多小时风险分析。']
 ],quiz:{q:'100 MW/200 MWh 储能为何不能把 100 MW 作为持续 10 小时的无条件供电承诺？',options:['因为能量与时长约束会限制持续出力','因为 MW 不能换算 kW','因为所有储能都不允许参加市场'],answer:0,explain:'持续 10 小时按 100 MW 发电需 1,000 MWh，明显超过 200 MWh，还需考虑 SOC 与效率。'},
 guide:{goal:'区分铭牌容量和认定能力，并用正确单位计算教学容量收入。',pre:[18],terms:['资源充裕性','可靠容量','容量机制','履约义务'],example:['认定能力比铭牌数值更关键','①自编资源装机 100 MW，但认定能力为 80 MW。②假设能力支付 100 元/(kW·年)。③80 MW 换为 80,000 kW。④年收入=80,000×100=800 万元。⑤再核对承诺期间、可用率和处罚；不能直接认为实际市场允许或采用本数值。'],task:['教学假设：认定能力 60 MW，年能力支付 80 元/(kW·年)。全年未计扣减的能力收入是多少？',4800000,'元/年','60 MW=60,000 kW；60,000×80=4,800,000 元/年。']},sources:[curriculumSources.adequacy,curriculumSources.capacity],pitfalls:['将铭牌 MW 无条件视作尖峰可靠容量。','将元/(kW·年) 与元/(MW·日) 混用。']},

 {id:20,title:'新能源、负电价与弃电：低价为什么不等于免费',desc:'比较供给不灵活、交易结算和新能源捕获电价，避免将负批发价套用户账单。',minutes:23,
 sections:[
 ['零燃料成本不等于零总成本','风光增发时燃料成本很低，但项目仍需投资、运维、土地、接入等支出。多个同类项目在相近时段发电，会扩大这些时段的供给并压低其获得的价格。评价新项目不能只看全年市场时间均价，要用自身实际发电曲线加权，观察出力与低价是否同时发生。'],
 ['为什么报价可能低于零','发电企业有时面对停机后重启成本、最小出力、调度约束或其他合同收益，短期可能接受为送出电能付费。负价表示该市场的交易价格方向反转，并不意味着电能没有物理价值，也不能把历史补贴制度假定为当前原因。分析一次负价要核对当地限价、网络和供需状态。'],
 ['直接算一次负价收入','自行设置风电在两个 1 小时时段发电 30 与 10 MWh，结算价格 −100 与 400 元/MWh。纯电能量收入=30×(−100)+10×400=1,000 元。总发电 40 MWh，捕获电价 25 元/MWh；价格简单平均却是 150。若用简单均价预测收入，会得到错误的 6,000 元。'],
 ['弃电、限电与经济选择','可发电但未上网的电量需要分清设备故障、天气偏差、网络或安全指令以及主动经济减发。前述负价时段是否允许减发、是否有补偿、是否违反合同都要核对。教学比较可设“无其他义务且允许减发”，现实项目则先看调度和合同，不能从负价自动推出停发就是合法最优。'],
 ['储能与用户为何不是无限受益','负批发电价时，储能也受充电功率、SOC、接入和交易资格限制；充入的电量还要承担损耗及之后价格风险。用户的到户账单可能包含固定费、网络费、税费或合同价，因此批发 −100 元/MWh 不等于所有消费者用电就获得同样退款。先区分市场主体和收费层次。']
 ],quiz:{q:'发电项目大部分发电发生在低价时段，最应关注哪种均价？',options:['自身发电电量加权的捕获电价','全年价格最大值','任意三个国家价格的平均值'],answer:0,explain:'捕获电价按项目实际发电曲线加权，可以反映发电与价格同时变化的影响。'},
 guide:{goal:'正确处理负价乘电量，并区分捕获电价与用户到户电价。',pre:[14,7],terms:['负电价','弃电','捕获电价','同向出力风险'],example:['正负收入按时段相加','①两个时段发电量 30、10 MWh，价格 −100、400 元/MWh。②收入分别 −3,000、4,000 元。③总收入=1,000 元，电量=40 MWh。④捕获电价=1,000÷40=25 元/MWh。⑤这只是发电侧纯能量收入，没有加入环境权益、合同差价或减发补偿。'],task:['自编项目在两个时段分别发 20、20 MWh，价格 −50、350 元/MWh。纯电能量总收入是多少？',6000,'元','20×(−50)+20×350=−1,000+7,000=6,000 元；不要忽略负号。']},sources:[curriculumSources.negative,curriculumSources.energy],pitfalls:['把负批发现货价直接当作用户完整到户电价。','用时间均价替代新能源出力加权价格。']},

 {id:21,title:'PPA、CfD 与环境权益：一份长约覆盖哪些风险',desc:'区分购电合同、金融差价与绿色属性，算出参考价错位后的敞口。',minutes:25,
 sections:[
 ['先问合同交付什么','PPA 通常指购电协议，可约定期限、电量、价格、交付、偏差和环境属性。实体交付型和金融结算型的安排不同，也不意味着电网为签约双方建立了专用路径。先列清合同覆盖电量曲线、计量点和结算价格，再判断哪些风险转移给谁。只看一项固定单价不足以理解协议。'],
 ['差价结算的三个价格','自编发电侧差价模型使用执行价 K、参考价 R 和项目实际售电价 S。现金收入=实发电量×S+合约结算电量×(K−R)。只有电量匹配且 S=R 时，合约部分才恰好锁到 K；项目节点价格与参考市场价格错位时，还存在基差风险，不能说价格已经完全固定。'],
 ['算一次不完全锁价','实发和结算电量均为 100 MWh，执行价 400、参考价 350、实际售电价 320 元/MWh。现货收入=32,000 元，差价收入=5,000 元，总计 37,000 元，而不是 40,000。差出的 3,000 元来自 100×(320−350)，不是发电量不足。这说明参考价定义与节点选择很重要。'],
 ['价格之外还有出力和对手方','若约定固定交付而设备出力不足，项目可能需要从市场补购；若按实际发电结算，买方则可能承担不稳定供应。期限、信用保证、提前终止、负价及不可抗力条款也会改变价值。英国政府支持型 CfD 是具体制度实例，不应把其期限或资格照搬为全球 PPA 的共同标准。'],
 ['绿色属性单独核对归属','电能量收入、差价结算和环境权益收入是三条账。合同可能已经把环境属性转给买方，那么项目不能又将同一属性出售并自称仍拥有绿色消费声明。美国 REC、中国绿证及其他证书制度在核发、注销和跨区认可上不同，必须查对应政策。经济模型可以分项，权益归属须有文件证据。']
 ],quiz:{q:'项目售电价 S 低于合约参考价 R，且其余条件相同，差价合约还留下什么风险？',options:['参考价与实际售电价之间的基差风险','所有价格风险必然消失','功率单位自动变为电量单位'],answer:0,explain:'差价按 R 算，但实际出售按 S，二者错位会留下基差敞口。'},
 guide:{goal:'把执行价、参考价和实际售电价分别写入公式，并核对环境权益归属。',pre:[3,7],terms:['PPA','CfD','基差风险','环境属性'],example:['三种价格不要只留一个','①实发=差价结算电量=100 MWh。②S=320，现货 32,000 元。③K=400、R=350，差价 100×50=5,000 元。④总收入 37,000 元。⑤如果 S=R=350，则 35,000+5,000=40,000，才在此简化模型下锁至 K。未计其他合同条款及权益。'],task:['实发与差价电量均 80 MWh，K=420、R=400、S=380 元/MWh。发电侧简化总收入是多少？',32000,'元','80×380+80×(420−400)=30,400+1,600=32,000 元。']},sources:[curriculumSources.cfd,curriculumSources.wholesale,curriculumSources.rec],pitfalls:['把执行价、参考价与实际售电价当成同一价格。','同一环境权益既随 PPA 转让又重复出售。']},

 {id:22,title:'零售账单与形状风险：用户和售电商算的不是一笔钱',desc:'逐项读懂到户费用，从用电曲线解释零售商风险。',minutes:25,
 sections:[
 ['从客户账单开始拆','零售用户账单可包含电能量、网络相关费用、基本或需量收费、税费及其他适用项目；每一项是否收取以实际地区和合同为准。先把按 kWh 的费用与按 kW、月或固定金额的费用分开。某张公开现货报价只能说明其中可能的一部分，不能作为整个账单的替代。'],
 ['做一个假设账单','自编用户月用电 10,000 kWh，电能量合同单价 0.50 元/kWh，假设网络相关按量费 0.20 元/kWh、固定服务费 200 元/月，无其他费用。电能量 5,000 元，按量网络费 2,000 元，固定费 200 元，总额 7,200 元。该费率组合不是任何省份的实际收费清单。'],
 ['用户付款不等于售电商利润','上例用户付 7,200 元，但网络部分可能由其他主体收取或经售电商转付。售电商评估的是合同售电收入减去批发购电、偏差、服务、信用及其他由其承担的成本。不能把到户总金额减一个现货购电成本后全部作为毛利；先确认收费归属及会计口径。'],
 ['总电量对上仍会有曲线风险','自编两个 1 小时时段实际用电 10 和 30 MWh；合同覆盖每时段各 20 MWh，合同价 400 元/MWh，现货价 200 和 600。买电成本=40×400+(10−20)×200+(30−20)×600=20,000 元。总实际与总合同都是 40 MWh，却不是仅按合同得 16,000，因为低价时多余、高价时不足。'],
 ['固定价服务到底承担了什么','固定零售单价能让用户电能量部分更可预测，但风险被谁承担要看合同的电量范围、价格调整、偏差和其他费用条款。签约前用逐时曲线重放历史，再做高价与电量错位情景；事后则将用户账单、售电商购电账和市场结算账分别复核，别把三份账混成一张。']
 ],quiz:{q:'月实际用电量等于合同总量，是否意味着不存在购电敞口？',options:['一定没有','仍可能因时段曲线错位产生敞口','只有总量超过合同才有风险'],answer:1,explain:'各时段多余和不足可能按不同现货价结算，月度相抵不能消除形状风险。'},
 guide:{goal:'分拆用户账单，并在总量相同的情况下算出曲线错位成本。',pre:[7,16],terms:['到户账单','形状风险','需量收费','固定价零售'],example:['月总量相同也要逐时算','①实际曲线 10/30 MWh，合同 20/20 MWh。②合同支出 40×400=16,000 元。③低价时多余 10 MWh 产生 −2,000 元调整，高价时不足 10 MWh 产生 +6,000 元调整。④总成本 20,000 元，比仅看总量高 4,000。此为买电侧简化逐时差价模型，不代表零售用户直接按此结算。'],task:['假设用户月用电 8,000 kWh，能量价 0.55 元/kWh，另有按量网络费 0.18 元/kWh及固定费 160 元/月，无其他费用。账单总额是多少？',6000,'元/月','8,000×(0.55+0.18)+160=5,840+160=6,000 元/月。本题是用户账单，不是售电商利润。']},sources:[curriculumSources.retail,curriculumSources.tariffs],pitfalls:['把到户网络与税费都计入售电商净收入。','认为月总量匹配就消除了所有曲线风险。']},

 {id:23,title:'市场力与监测：高价何时值得调查',desc:'用枢纽供应商与集中度指标筛查风险，再寻找约束和行为证据。',minutes:24,
 sections:[
 ['高价格可能有不同原因','价格上升可能来自燃料变贵、负荷高、故障、线路限制或合法稀缺机制，也可能与供应商策略有关。市场力描述影响市场价格或排挤竞争的能力，滥用则涉及具体行为及规则判断。教学上先建立竞争性成本与可行供给的参照，再比较报价和可用性，避免只看到高价就下结论。'],
 ['检验谁在这个时段不可缺少','自编系统需求 100 MW，供应商 A/B/C 可用能力为 60/30/30 MW。若去掉 A，其余只有 60 MW，不能满足 100，因此 A 是本例枢纽供应商；去掉 B 则剩 90，也不足，所以 B 也可能关键。容量总和大于需求，不保证每一家都没有定价影响力，分析必须依赖此时的可用容量。'],
 ['集中度筛查能告诉多少','按自编市场份额 50%、30%、20%，HHI=50²+30²+20²=3,800。该指标提示结构集中程度，不能单独证明某次报价违规。小时需求、局部线路和备用使相关市场范围变化；全国年度份额很小的公司，也可能在特定受限区域的某些时段具有关键作用。'],
 ['行为证据要与成本对应','可以检查报价突变、可用容量申报、计划与非计划停机、燃料成本、关联交易和报价调整规则。经济性高报价与真实设备故障的含义不同；启停磨损、稀缺及机会成本又可能合理解释部分变化。研究者应记录假设与替代解释，正式违规认定交由有权限机构按规则作出。'],
 ['监测与缓解也有代价','成本审核、报价约束、信息披露和结构性措施针对不同问题，设计不当也可能削弱投资或短期灵活性信号。规则阅读应问触发条件、参考成本、申诉流程和处理结果。本课的枢纽测试和 HHI 都是筛查工具，不是对真实企业的违规标签，也不能代替各市场完整监测标准。']
 ],quiz:{q:'某公司在高峰小时是枢纽供应商，能立即据此判定其违法操纵了吗？',options:['可以直接判定','不能，还需行为、成本与适用规则证据','意味着其所有报价必然等于零'],answer:1,explain:'枢纽测试说明结构性能力与风险，不单独证明已经实施违规行为。'},
 guide:{goal:'计算简单集中度和枢纽供应商测试，并说明它们只是筛查。',pre:[14,19],terms:['市场力','枢纽供应商','HHI','市场监测'],example:['把一家去掉再检查平衡','①需求 100 MW，可用容量 A60/B30/C30。②移除 A，剩 60<100；移除 B，剩 90<100；移除 C 也剩 90。③各家在这个简化时段都可能关键。④还须核对进口、需求响应、线路和报价行为。⑤不要用“总容量 120>100”直接断言市场充分竞争。'],task:['三个供应商的教学市场份额分别为 60%、25%、15%。采用百分数平方相加的口径，HHI 是多少？',4450,'点','HHI=60²+25²+15²=3,600+625+225=4,450。它不直接给出违规结论。']},sources:[curriculumSources.conduct,curriculumSources.primer],pitfalls:['把高价或 HHI 较高直接当作违法证明。','用全国年度份额替代局部受限小时的市场分析。']},

 {id:24,title:'储能 SOC 与调度边界：有价差也不一定能赚到',desc:'用逐时能量守恒检查充放电、终端电量和多种收益的物理可行性。',minutes:27,
 sections:[
 ['把电池里的能量当作状态','设 E 为内部储能量，单位 kWh，容量为 200 kWh，SOC=E/200。初始 E=100 kWh 对应 50%。允许 10%—90% SOC，则可用范围为 20—180 kWh，不是从 0 到 200 随便用。容量会随衰减变化；可用区间、保留备用和温度条件应取设备与项目资料。'],
 ['分开充电效率和放电效率','采用交流侧功率：E下一时段=E当前+η充×P充×时长−P放×时长÷η放。η充=η放=95% 时，往返效率为 90.25%，不是 95%。从电网充入 50 kWh，内部增加 47.5；向电网放出 38 kWh，内部减少 40。效率位置写错会凭空产生电量。'],
 ['能量、功率与接入一起约束','假设最大充放功率 50 kW，半小时最多从电网充入 25 kWh；还要检查 SOC 上限剩余空间。共用变压器或并网点时，光伏、负荷和储能共同受其功率限制。一般教学调度也应避免无理由同一时段同时充放，不能分别把两个方向最大功率都算作盈利资源。'],
 ['期末电量不能凭空送给模型','若模拟最后一天把电池放空，就会获得一笔收入，但下一天需要恢复能量。比较两个运行方案时，应采用相同初末 SOC 或明确期末剩余能量价值。本课用 E期末=E期初约束，让不同方案可公平比较；备用承诺还需在事件开始前留够能量，而非只满足年平均值。'],
 ['从物理轨迹再走到钱','逐时计算并网点购售电量及费用，再扣运维、衰减和更换等成本。需求费削减取决于计费峰值是否真的降低，调频和备用取决于当时能量与功率能否履约。把每个收益模型的独立最优值相加可能违反同一套物理约束。盈利设计先要有一条统一、可实现的 SOC 轨迹。']
 ],quiz:{q:'充电效率与放电效率各 95%，教学模型中的往返效率是多少？',options:['95%','90.25%','190%'],answer:1,explain:'往返过程经过两个效率环节：0.95×0.95=0.9025。'},
 guide:{goal:'按明确交流侧口径更新 SOC，并检验初末能量一致与收益互斥。',pre:[12,15],terms:['SOC','能量状态方程','充放电效率','终端 SOC','收益互斥'],example:['先画三行能量轨迹','①容量 200 kWh、初始内部能量 100，SOC 50%。②以 50 kW 充 1 小时，η充95%，E=100+47.5=147.5，SOC73.75%。③以 38 kW 放 1 小时，η放95%，E=147.5−38/0.95=107.5，SOC53.75%。④两步均假设符合功率与 SOC 约束；回到 50% 还需再处理 7.5 kWh 内部能量，不能忽略终端差异。'],task:['电池内部初始能量 100 kWh，以交流侧 40 kW 充电半小时，充电效率 90%，无其他损耗。期末内部能量是多少？',118,'kWh','电网输入=40×0.5=20 kWh；内部增加 20×0.9=18；期末 100+18=118 kWh。']},sources:[curriculumSources.battery,curriculumSources.operations],pitfalls:['只乘一次效率却同时宣称覆盖完整充放过程。','靠期末放空电池夸大日收益，或重复占用同一容量。']},

 {id:25,title:'虚拟电厂与需求响应：少用了多少电怎样证明',desc:'理解资源聚合、基线和响应核验，把名义能力变成可验证交付。',minutes:25,
 sections:[
 ['虚拟电厂是协调与交付关系','VPP 把分散的光伏、储能、电动车和可调负荷等聚合，通过预测、通信与控制提供服务。它不是增加一块实体发电机，也不是把所有设备铭牌容量简单相加就得到稳定能力。要识别谁有控制权、谁能退出、数据多久更新、调度失败由谁承担，才能估算可调用规模。'],
 ['需求响应的反事实问题','发电量可以直接计量，但“本来会用多少电”无法在响应日同时观察。基线就是规则规定的无响应参考量。它可能依历史日、天气和生产条件调整；低于基线的差额还要经过资格、事件窗口及核验。停产、自然天气变凉等导致的低用电，未必都能当作响应成果。'],
 ['用一个透明平均基线练习','仅为教学设定：前三个相似日同一小时负荷为 100、110、90 kW，基线取平均 100 kW。事件小时实际 70 kW，认定减量 30 kW；持续 1 小时，响应电量 30 kWh。若假设补偿 2 元/kWh，金额为 60 元。实际规则可能使用不同天数、剔除和调整方法，不能直接照搬。'],
 ['核验净收益与反弹用电','若响应后需要额外用电补生产，应把反弹期费用和生产影响纳入经济分析。储能放电降低并网点购电，也须明确是否符合该产品资格、是否已经计入其他服务。少用电的账单节省与事件补偿可能有不同归属及互斥条款，最终应按单一计量边界和合同记账，避免重复。'],
 ['聚合还要管理交付不确定性','100 家设备每家承诺 10 kW，名义合计 1 MW；同时停机、用户退出或通信故障会使实际不足。采用可用率、相关性和事件持续时间情景，给出保守可交付能力，且保留逐设备计量与控制记录。规则阅读重点是注册、通知、基线、数据质量、性能考核和收益分成。']
 ],quiz:{q:'需求响应的基线主要解决哪个问题？',options:['估计没有响应时的参考用电','证明所有少用电都是主动响应','把用户负荷自动变成发电铭牌容量'],answer:0,explain:'基线是反事实参考，需要按规则核验，不能将所有自然减量都归因于响应。'},
 guide:{goal:'计算一个透明基线下的响应电量，并区分响应补偿与账单节省。',pre:[18,22],terms:['VPP','需求响应基线','响应电量','反弹效应','聚合商'],example:['每一步都留下计量口径','①自编基线采用三个相似日同小时平均：(100+110+90)/3=100 kW。②事件实际 70 kW，减量 30 kW。③持续 1 小时，响应电量 30 kWh。④假设 2 元/kWh 补偿，得到 60 元。⑤未计反弹、服务费和考核，且本平均法不是任何地区的完整基线规则。'],task:['教学基线 120 kW，事件平均实际 80 kW，持续 30 分钟，假设补偿 3 元/kWh且无扣减。事件补偿是多少？',60,'元','减量 40 kW；响应电量 40×0.5=20 kWh；补偿 20×3=60 元。']},sources:[curriculumSources.vpp,curriculumSources.dr,curriculumSources.retail],pitfalls:['抬高非事件日用电以虚增基线。','把自然停产、储能节费和响应交付无条件重复计入收益。']},

 {id:26,title:'项目现金流、NPV 与敏感性：回本快就一定好吗',desc:'从运行毛收益进入全周期评价，用折现与情景比较光储综合方案。',minutes:28,
 sections:[
 ['统一评估边界与比较基准','先选项目整体或投资人权益视角，列建设、接入、运维、保险、租金、税费、设备更换、残值及其他已核实项目。用户侧节费是与无项目账单比较的增量价值，发电侧则是销售等现金流，两者不能重复表示同一度电。负荷、价格、设备寿命和地区规则应使用一致期间。'],
 ['运行毛收益不是年净现金流','每天价差收益只是起点。全年要考虑可运行日、维护、衰减与充电约束，再减相关支出。折旧是利润表上的非现金项目，但可能影响税款；借款本金偿还与利息则影响资金流。全投资模型与权益模型不能把债务支出扣两遍，也不能直接套国外工具默认的税费。'],
 ['折现处理不同时间的钱','净现值 NPV=初始投资负值+各期净现金流/(1+r)的期数次方。教学设初始投资 100 万元，未来三年每年末净现金流 40 万元，折现率 10%，无残值：现值分别 36.36、33.06、30.05 万元，合计 99.47，NPV≈−0.53 万元。名义累计 120 万并不保证折现后有吸引力。'],
 ['回收期与 NPV回答不同问题','按年内均匀回收的常用近似，上例静态回收期约为100÷40=2.5年；若严格只在年末收到现金，第三年末才覆盖投入。静态回收强调不折现的回收速度；NPV衡量给定折现率下整个期间的净价值。若存在更换或停运，不能用恒定年收益直除代替逐年累计。比较寿命不同的方案还要统一分析期和期末残值，避免短期方案被任意延长。'],
 ['敏感性先找到决定性输入','分别改变价差、投资、效率、利用率、寿命或认定服务收入，观察 NPV变化，再设计相互一致的低/中/高情景。单因素敏感性用于定位驱动，多个不利因素可能同时发生。尚无资格和合同证据的服务收入可单列待核实情景，不写入确定基准；结果是条件判断，不是保证收益。']
 ],quiz:{q:'为什么静态回收期较短，NPV仍可能为负？',options:['回收期不折现且不能完整反映后续支出与分析期','NPV只比较机组容量','折现率越高未来现金流越值钱'],answer:0,explain:'NPV考虑时间价值及整个分析期现金流，静态回收速度不能替代它。'},
 guide:{goal:'区分现金流与运行毛收益，手算短期 NPV并说明关键假设。',pre:[12,24],terms:['净现值 NPV','折现率','静态回收期','敏感性分析','增量现金流'],example:['把今天与未来分别写一行','①第 0 年投资 100 万元，现金流 −100。②第 1—3 年末各 +40，r=10%。③现值 40/1.1=36.3636，40/1.1²=33.0579，40/1.1³=30.0526。④NPV=−100+99.4741=−0.5259 万元。⑤这是假设净现金流已经扣完题面约定成本，无残值，也不是实际项目建议。'],task:['教学项目第 0 年投入 100,000 元，第 1 年末净现金流 60,000 元，第 2 年末 60,000 元；折现率 10%，无残值。NPV保留两位小数是多少？',4132.23,'元','−100,000+60,000/1.1+60,000/1.1²=4,132.2314 元，保留两位为 4,132.23。']},sources:[curriculumSources.npv,curriculumSources.finance],pitfalls:['把日运行毛收益直接乘 365 作为完整年净现金流。','混用全投资与权益视角导致融资成本重复扣除。']}
];

const expandedGlossary={
 '热耗率':'生产单位电能耗用的燃料能量；先核对 GJ/MWh 等单位及热值口径。',
 '增量成本':'增加一单位产出所增加的成本；短期分析通常先考虑新增运行支出。',
 '贡献毛益':'收入减新增或变动运行成本后的差额，仍需覆盖固定成本等。',
 '稀缺定价':'在系统能力紧张时表达边际稀缺价值的定价安排，具体触发和限价依规则。',
 '愿付价格':'教学需求对新增单位电量的价值上限，不是完整用户账单价格。',
 '社会福利':'本课简化模型中的总用电价值减真实供给成本；忽略未列明外部性。',
 '消费者剩余':'用电价值减购买电能量的付款，是需求侧在模型中的收益。',
 '生产者剩余':'售电收入减模型中的变动供给成本，不能直接等于项目净利润。',
 '机组组合':'确定各机组在各时段是否开机，通常涉及启停与最小开停机时间。',
 '最小出力':'机组开机后可稳定或被规则认可运行的最低功率。',
 '爬坡约束':'相邻时段出力变化的上限，必须注明时间间隔或速率单位。',
 '启动成本':'机组从停机转为运行产生的特定成本，与单位电量变动成本不同。',
 'Uplift':'某些市场中用于特定成本或调度补偿的额外支付类别，条件与分摊依当地规则。',
 '负荷曲线':'按真实时间排列的用电功率序列，可换算各时段电量。',
 '负荷持续曲线':'将负荷按大小排序后的曲线，用于看不同负荷水平持续多久；不保留运行先后。',
 '电量加权均价':'各时段电量乘价格的总和除以总电量；总电量为零时该指标不定义。',
 '负荷率':'一段期间平均负荷除以最大负荷，描述曲线平坦程度，不等于设备效率。',
 '捕获电价':'项目实际发电量加权的售电价格，体现发电时段与价格的对应关系。',
 '节点平衡':'某节点供给加流入等于需求加流出，本课无损模型使用该等式。',
 '影子价格':'在约束状态不变附近，放宽单位约束对最优目标的边际影响。',
 '阻塞剩余':'教学节点结算中由受限输送和节点价差形成的付款差额；分配需看规则。',
 '机会成本':'选择一个用途时所放弃的最好可行替代用途价值。',
 '备用能力':'按产品要求可以被调用的响应功率与持续能力，不等于已经发出的电量。',
 '联合优化':'在同一套物理约束下同时安排电能量与服务等用途。',
 '性能考核':'核验资源实际响应是否达到产品要求，并据规则影响报酬或处罚。',
 '资源充裕性':'在给定需求、故障和不确定性下，系统资源满足供电需求的能力。',
 '可靠容量':'按指定方法认定资源在系统需要时的有效供给或减负荷能力。',
 '容量机制':'为资源可用能力及其义务安排采购或补偿的一类制度，形式因市场而异。',
 '履约义务':'取得交易或能力收入后应满足的交付、可用性、数据与其他合同要求。',
 '负电价':'结算价格低于零，纯电能量交易方向可能变为卖方付费给买方。',
 '弃电':'可生产或可送出的电量未实现上网，原因和计量口径须明确。',
 '同向出力风险':'许多类似资源在相近时段集中发电，使自身发电加权价格承压的风险。',
 'PPA':'购电协议，需读电量、价格、期限、交付及环境属性等具体约定。',
 'CfD':'按执行价与参考价之间差额结算的合同结构；具体设计并不全球统一。',
 '基差风险':'实际交易价格与合约参考价格不同而留下的价格敞口。',
 '环境属性':'可再生能源等特征对应的权益或证明，需确认核发、转让与注销归属。',
 '到户账单':'最终用户应付费用的完整账单，可包含能量、网络、固定和其他适用费用。',
 '形状风险':'合同与实际电量在各时段分布不同造成的价格或数量敞口。',
 '需量收费':'按规则定义的功率或需量等而非仅按总电量收取的费用。',
 '固定价零售':'按合同约定为用户提供固定单价安排，其他费用和调整条款仍需核对。',
 '市场力':'主体影响市场价格或竞争结果的能力；具备能力不等于已经违规。',
 '枢纽供应商':'去掉该供应商后剩余可用能力不足以满足给定需求的供应商。',
 'HHI':'市场份额平方和的集中度指标，本课采用百分数平方口径；只是筛查。',
 '市场监测':'收集并分析市场结构、成本和行为数据，以识别并处理运行与竞争风险。',
 'SOC':'电池当前内部能量占指定容量的比例；容量和测量侧需说明。',
 '能量状态方程':'把上一时段能量、充电输入、放电输出和损耗连接起来的守恒关系。',
 '充放电效率':'输入、存入和输出能量之间的比例，充电与放电效率相乘得到往返效率。',
 '终端 SOC':'模拟或计划结束时的电池状态；比较方案须用一致终端条件或价值。',
 '收益互斥':'不同用途争用同一资源或不允许重复结算，不能无条件相加。',
 'VPP':'虚拟电厂，通过协调聚合分布式资源提供可验证服务的组织与技术方式。',
 '需求响应基线':'按指定方法估计没有响应时本来会用的电，是核验减量的参考。',
 '响应电量':'按事件时段、基线与实际计量核验的减负荷电量，不等于全年节电量。',
 '反弹效应':'事件后恢复生产、充电或温度等造成额外用电，需纳入全时段评价。',
 '聚合商':'将多个资源组织为可参与产品的主体，权利、责任和收益分配取决于规则合同。',
 '净现值 NPV':'按折现率将未来净现金流换算到基准时点，再减投资后的价值。',
 '折现率':'把不同时间的现金流换算到共同基准所使用的比率，应与现金流口径一致。',
 '静态回收期':'不折现累计净现金流覆盖初始投入所需时间，不能替代完整价值判断。',
 '敏感性分析':'改变关键输入观察结果变化，用于找出最影响结果的假设。',
 '增量现金流':'有项目与无项目情景的现金收支差额，避免把基准费用重复记为收益。'
};

const originalEnrichments={
 0:{sections:[['变化功率要分段累计','若设备前半小时为 40 MW、后半小时为 60 MW，总电量=40×0.5+60×0.5=50 MWh。把末尾的 60 MW 乘整个小时会多算 10 MWh。计量曲线通常给区间平均值；瞬时读数、区间电量和累计电表差值各自含义不同。整理资料时每行注明起止、时长及数值类型，再检查各行电量合计。'],['能量费只是账单的一部分','单位统一后，电量乘单价得到对应电能量费用。如果另有按功率或月份收取的项目，必须另列公式，不能也乘 MWh。比如教学设 100 kW 需量按 30 元/(kW·月) 计费，月金额为 3,000 元，与当月用电量不是同一乘法。计算前标明是批发购电、发电收入还是用户到户账单。']],sources:[curriculumSources.operations,curriculumSources.tariffs],pitfalls:['将一个瞬时功率读数当作整个时段平均值。','把能量、功率和月固定费用混用。']},
 1:{sections:[['物理流与交易关系分别画','电流在网络中遵循物理规律，合同则约定交付与结算权利义务。用户向某售电商购电，不代表每个电子都来自合同指定机组。学习时可以画两张图：第一张是电源—网络—用电的物理连接，第二张是发电商、零售商和用户的合同关系，分别标注计量点和付款方向。'],['责任划分决定收益边界','不要只背主体名称，还要问谁预测负荷、谁申报交易、谁承担偏差、谁收取网络费用、谁保证设备响应。自编例中用户采用固定能量价，售电商购电成本却随批发价和曲线变化；价格风险可能留在售电商，但合同调整条款也可能转回用户。每项收入和成本都应归属到具体主体。']],sources:[curriculumSources.wholesale,curriculumSources.retail],pitfalls:['认为合同交易必然对应一条专属物理输电路径。','不读风险分配就假定某类主体总是承担偏差。']},
 2:{sections:[['预测在每个时点都会更新','在月初安排购电时只能使用当时可见的生产计划和天气；日前又可以更新，临近运行还会变化。复盘要保存各时点预测，不能用事后实际数据替代当时决策输入。自编例：月初预计 100、日前更新 108、实际 110 MWh，既要分析日前为何增加 8，也要分析最后剩余 2 的原因。'],['安排成交不意味着预测误差消失','合同可降低部分价格敞口，但不消除故障、天气和用电曲线偏差。交易截止时间、可调整窗口、实际交付时段和结算期间是不同概念；把日内调整写成实时结算也会误读规则。为每项产品建立“何时申报—覆盖何时运行—按什么价格结算”的三列表，再比较不同地区。']],sources:[curriculumSources.operations,curriculumSources.energy],pitfalls:['用事后实际曲线回填原始预测，低估预测风险。','混淆交易截止、交付时间和结算周期。']},
 3:{sections:[['套期保值先匹配曲线与地点','合同月总量恰好等于实际总量，并不表示每个时段都匹配。低价时段合约多、高价时段合约少，仍可产生购电或售电差额；项目节点价与合约参考价不同，也留下基差。把总公式扩为各时段求和，再记录合同覆盖点、价格参考点和计量点，才能判断风险真正被覆盖了多少。'],['过度签约也会出现相反敞口','发电侧教学模型设合同 100 MWh、实发 70，合同价 350、现货价 500 元/MWh：收入=70×500+100×(350−500)=20,000 元。不能按合同 100×350 直接写 35,000。少发的 30 MWh 暴露于较高现货价；现实合同如何交割和偏差处理，必须按具体文本核对。']],sources:[curriculumSources.wholesale,curriculumSources.cfd],pitfalls:['只检查月总量覆盖而不核对逐时曲线。','认为签约越多一定越安全。']},
 4:{sections:[['排序结果要通过平衡和约束检查','先检查各机组出力不小于零、不超过容量，总出力等于需求，再讨论价格。需求从 180 变为 181 MW 时，课程模型新增 1 MW 必须由 C 提供，价格因而从 B 的档位进入 C 的档位。若需求大于总容量 300，先报告缺额；报价排序不会创造额外供给，也不能自行指定停电时的结算价。'],['成交价与发电成本不是同一账','假设 A 成本等于报价 180、成交价 300，1 小时发 80 MWh。A 能量收入 24,000 元，简化变动成本 14,400，差额 9,600 元。统一边际价格让较便宜供给获得贡献毛益，但项目仍有固定支出。不要把这个差额当作所有省份实际净利润，也不要按报价分别付款又声称采用统一价格。']],sources:[curriculumSources.micro,curriculumSources.load],pitfalls:['统一价格模型里却给每家按自身报价结算。','供给缺额时仍宣布已完整出清。']},
 5:{sections:[['一份设备容量要先核对用途','备用能力常按 MW 和承诺持续期记录，电能量按 MWh 记录；调频还有响应性能等要求。储能若已为高价时段满功率放电，不能同时默认留有同样的向上备用。先列统一时段计划与功率、能量约束，再分别算不同服务收入，才能避免把多个独立最优结果直接相加。'],['环境价值的出售与声明相连','绿色环境属性可能随绿电合同转移，也可能依据制度单独交易。课程将能量费、服务费和环境属性费分列，是为了帮助检查权益；并不意味着每个项目都有三份确定收入。自编复核问题：该份环境属性是否已经转让？由谁注销？谁能声明绿色消费？如无依据，应标记待核实而不是再记一笔收益。']],sources:[curriculumSources.services,curriculumSources.rec],pitfalls:['重复出售或宣称同一环境属性。','忽略备用和能量争用同一容量。']},
 6:{sections:[['让时段长度进入收入计算','需求 220 MW 时，C 出力 40 MW；若时段只有 15 分钟，C 电量是 10 MWh，而不是 40。按 480 元/MWh 的统一价格，其能量收入为 4,800 元。短时市场把功率用于出清、把电量用于结算，二者靠时长连接。改变时间颗粒度时，要同时检查报价单位、结算电量和相邻时段爬坡。'],['通过变化量检验边际含义','比较需求 220 与 221 MW，A、B 不变，C 多 1 MW；在 1 小时时段、成本等于报价的假设下，总运行成本增加 480 元。这个增量解释了边际价格，而全部运行成本除总电量得到的是平均成本。两者一般不同；若跨越容量边界、网络或其他约束改变，也不能继续沿用原增量。']],sources:[curriculumSources.micro,curriculumSources.energy],pitfalls:['把 MW 直接乘元/MWh而遗漏时间。','把系统平均成本当作边际价格。']},
 7:{sections:[['两结算与全量实时价格的差','买电成本可重写为实际电量×实时价+日前电量×(日前价−实时价)。这说明日前安排相当于对部分电量的价差覆盖，而非实际所有电量再付一次实时费。以 100、110 MWh 和 300、450 元/MWh为例，全量实时为 49,500，日前价差为 −15,000，合计仍 34,500 元，两种写法应相等。'],['逐时核对偏差方向与来源','负偏差表示实际小于参考安排，在本买电模型中产生抵减，但它不保证总成本一定低于实际电量按日前价计算。多时段偏差先分别乘对应实时价再相加，不能将正负电量抵消后统一乘月均价。预测误差、设备故障和生产变化要分别记录；用户零售账单还需按合同再做映射。']],sources:[curriculumSources.energy,curriculumSources.wholesale],pitfalls:['日前部分加上全部实际实时电量，重复付款。','先把各时段偏差相抵再套一个均价。']},
 8:{sections:[['节点价问的是新增而不是平均','某位置已有的电由便宜电源供应，不代表再增加一度电仍能沿同一路径送达。如果线路已满，增量需求可能必须由本地更贵机组满足。用“此处增加 1 MW，最便宜的可行调整是什么”提问，比观察历史平均供给成本更接近节点价格的边际含义，同时要保持约束状态和时间口径一致。'],['局部价差不能直接推断利润','无损两节点模型里，线路满载和两端价差可能形成阻塞相关结算剩余。实际分配、金融输电权、损耗与附加费用依市场设计，价差不自动等于输电企业利润。规划储能选址时，还应看该节点的持续价格序列、接入容量和能否售电；不能只抓某一次尖峰价差就外推全年盈利。']],sources:[curriculumSources.network,curriculumSources.energy],pitfalls:['以已有供给平均成本代替新增负荷边际成本。','把节点价差无条件视作项目可获得收入。']},
 9:{sections:[['把每一条结论连接到证据','阅读笔记建议保存原件版本、条款或页码、原文要点、适用主体、参数单位以及你的解释。例如储能能否参加某服务，先找注册与产品准入，再找能力测试、计量、结算和考核；只找到“鼓励储能发展”不能证明所有产品资格已具备。解读和新闻帮助定位，完整权利义务仍以有效正文为依据。'],['用流程验证你是否真正读懂','选一个真实业务问题，写出注册—申报—出清—计量—结算—异议的流程，逐步填入负责机构、截止时间和所需数据。若某一步找不到条款，就标记待核实，不用外省经验补成确定结论。特别留意正文中的例外、过渡安排、配套附件和修订通知，它们可能改变看似清楚的一项参数。']],sources:[curriculumSources.basic,curriculumSources.wholesale],pitfalls:['以政策鼓励代替具体准入资格。','找不到条款时用外省参数补成确定答案。']},
 10:{sections:[['采用统一问题而不是统一数值','跨地区比较先设同一问题：谁承担实时偏差、在哪个点计量、采用什么参考价格、按何时段交付。然后各地区填入带版本的证据。若一处是批发主体、一处是零售用户，就不宜直接排名“哪省电价更便宜”。国家之间更要区分多个区域市场、受监管零售和不同币种及费用范围。'],['相同输入与相同权限一起核对','自编方案在甲地取得辅助服务资格，在乙地尚未取得；即使技术参数相同，也不应给乙地自动加同一服务收入。比较结果要分清技术经济条件、市场资格和政策支持。价格、运行小时和合同假设可以做情景，正式资格或强制费用不能靠情景假装已经确认；资料表应显示这种差别。']],sources:[curriculumSources.wholesale,curriculumSources.tariffs],pitfalls:['只比较一项现货价就评价完整到户成本。','把区域市场设计简化为全国唯一模式。']},
 11:{sections:[['用可复算的桥接拆解变化','自编两个时期电量为 100、110 MWh，加权价格为 300、350 元/MWh，能量成本从 30,000 到 38,500，增加 8,500 元。先固定旧价看电量变化：10×300=3,000；再按新电量看价格变化：110×50=5,500，两项加总一致。这里明确先量后价；换分解顺序时交互项归属会变化。'],['复盘保留当时的信息与行动','再把价格变化分为合同、现货、曲线和其他费项，并记录当时是否可以调整，而不是用后见之明指责预测。比如一次故障发生在高价时段，可能同时影响实际量和偏差价格，单因素分析不能代表联合风险。复盘最后应对应到数据改进、合同曲线或预警行动，并保留下一次验证结果。']],sources:[curriculumSources.retail,curriculumSources.wholesale],pitfalls:['分解电量与价格时漏掉交互项或不说明顺序。','用事后信息假定当时可以完美预测。']},
 12:{sections:[['自用光伏同样有机会成本','若光伏电原可按 0.35 元/kWh 外送，将 100 kWh 送入储能而不外送，就放弃 35 元收入。假设放出 88 kWh，替代用户购电价 0.80，其价值 70.40 元；相对直接外送的运行增量毛收益为 35.40 元。不能把光伏电的购电成本写零，就当作没有任何经济成本；还要核对自用与外送资格。'],['综合方案先做无项目对照','光伏、储能和可调负荷共用一个并网点时，先算无项目账单，再算统一功率和 SOC约束下的项目账单差额。储能削峰是否降低需量收费，取决于真实计费峰值；光伏节费不能在储能放电时再次重复记同一份电。之后加入投资、运维、衰减、更换和已确认服务现金流，才进入全周期评价。']],sources:[curriculumSources.battery,curriculumSources.finance],pitfalls:['将光伏充电当作完全没有机会成本。','光伏自用、储能放电和需求响应重复记同一份节费。']}
};
